INSERT INTO `events`
  (`organizer_id`, `artist_id`, `category_id`, `event_name`, `slug`, `description`, `event_date`, `start_time`, `end_time`, `venue_name`, `address`, `city`, `state`, `ticket_info`, `event_rules`, `official_url`, `poster_image`, `gallery_images`, `event_status`, `verification_status`, `trust_level`, `rejection_reason`, `admin_verification_notes`, `tracking_code`, `promoter_name`, `submitter_name`, `submitter_email`, `evidence_link`, `organizer_name`, `organizer_social_url`, `organizer_type`, `submitter_social`, `created_at`, `updated_at`)
SELECT
  (SELECT `id` FROM `users` WHERE `username` = 'livenation_my'), (SELECT `id` FROM `artists` WHERE `name` = 'BABYMONSTER'), (SELECT `id` FROM `event_categories` WHERE `slug` = 'concert'), '2026-27 BABYMONSTER WORLD TOUR [춤 (CHOOM)] IN KUALA LUMPUR', '2026-27-babymonster-world-tour-choom-in-kuala-lumpur', 'BABYMONSTER bring their first world tour [춤 (CHOOM)] to Kuala Lumpur. Presented by Live Nation Malaysia.', '2026-11-14', '17:00:00', '20:00:00', 'Unifi Arena (Axiata Arena), Bukit Jalil', 'Kompleks Sukan Negara, Bukit Jalil, 57000 Kuala Lumpur', 'Kuala Lumpur', 'W.P. Kuala Lumpur', 'SOLD OUT. Official ticketing: GoLive Asia only.', '1. Admission by ticket only; re-entry is not permitted.
2. No professional cameras, DSLRs or telephoto lenses.
3. Official artist lightsticks only; no laser pointers.
4. Bags are subject to security screening; no outside food or drinks.
5. No smoking, vaping, or alcohol inside the venue.', 'https://www.livenation.my/event/2026-27-babymonster-world-tour-%EC%B6%A4-choom-in-kuala-lumpur-kuala-lumpur-tickets-edp1682916', 'https://networksites.livenationinternational.com/networksites/5cabpce0/babymonster-group_press.jpg', '["https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=1200&auto=format&fit=crop","https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=1200&auto=format&fit=crop"]', 'UPCOMING', 'VERIFIED', 'VERIFIED', NULL, 'Verified from official promoter (Live Nation Malaysia). Sold out at time of import.', 'KSYNC-IMP-2026-0001', 'Live Nation Malaysia', 'K-Sync Editorial', 'imports@ksync.my', 'https://www.livenation.my/event/2026-27-babymonster-world-tour-%EC%B6%A4-choom-in-kuala-lumpur-kuala-lumpur-tickets-edp1682916', 'Live Nation Malaysia', 'https://www.instagram.com/livenation.my', 'Promoter', '@ksyncmalaysia', NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `events` WHERE `event_name` = '2026-27 BABYMONSTER WORLD TOUR [춤 (CHOOM)] IN KUALA LUMPUR' AND `event_date` = '2026-11-14');

